    let label = message(label, label_args)?;
    let (badge, badge_args) = (body.bytes()?, body.bytes()?);
    let badge = message(badge, badge_args)?;
    Ok(Command::SetItemState {
        item,
        flags,
        label,
        label_args,
        badge,
        badge_args,
    })
